"""Assemble experiments/2026-10-17/RESULTS.md from scoring/*.json, spend.json and the raw checkpoints. No API calls.
Usage: python -P experiments/2026-10-17/scripts/results_md.py [--deviations deviations.md]
The per-field table, task tables and spend are generated; the narrative sections (summary, deviations, limitations) are
read from scoring/results_narrative.md if present so that hand-written commentary is kept across regenerations.
"""
import json, os, sys, glob, collections
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
from score import UNITS, EXTRACTORS, EXP, SCORING, RAW, ARMS  # noqa: E402

def fmt(x, nd=2): return '—' if x is None else f'{x:.{nd}f}'

def main():
    ft = json.load(open(os.path.join(SCORING, 'field_table.json'), encoding='utf-8'))
    ta = json.load(open(os.path.join(SCORING, 'task_a.json'), encoding='utf-8'))
    tb = json.load(open(os.path.join(SCORING, 'task_b.json'), encoding='utf-8')) if os.path.exists(os.path.join(SCORING, 'task_b.json')) else None
    spend = json.load(open(os.path.join(EXP, 'spend.json'), encoding='utf-8'))
    for extra in ('spend_judge.json', 'spend_rater.json'):  # D3: concurrent passes kept their own ledgers
        q = os.path.join(EXP, extra)
        if os.path.exists(q):
            e = json.load(open(q, encoding='utf-8'))
            for m, d in e['by_model'].items():
                t = spend['by_model'].setdefault(m, {'usd': 0.0, 'calls': 0, 'input_tokens': 0, 'cached_input_tokens': 0, 'cache_write_tokens': 0, 'output_tokens': 0})
                for k in t: t[k] += d.get(k, 0)
            spend['total_usd'] += e['total_usd']; spend['calls'] += e['calls']
    spend_pilot = json.load(open(os.path.join(EXP, 'spend_pilot.json'), encoding='utf-8')) if os.path.exists(os.path.join(EXP, 'spend_pilot.json')) else {'total_usd': 0, 'calls': 0}
    narrative = open(os.path.join(SCORING, 'results_narrative.md'), encoding='utf-8').read() if os.path.exists(os.path.join(SCORING, 'results_narrative.md')) else ''
    short = {m: m.replace('claude-', '').replace('gpt-', 'gpt') for m in EXTRACTORS}
    L = ['# RESULTS — v0.9 field experiment (2026-10-17)\n',
         'Generated by `scripts/results_md.py` from `scoring/field_table.json`, `scoring/task_a.json`, `scoring/task_b.json`, `spend.json` and the raw checkpoints under `raw/`. Pre-registration: `docs/discovery/ontology-crosswalk-2026-10/experiment-plan.md` (commit `pre-registration frozen`). Thresholds are the frozen ones (§4.1 there); nothing below was chosen after seeing the data.\n']
    L.append(narrative)
    # ---- outcome summary
    L.append('\n## 1. Per-field outcomes\n')
    L.append('Outcome per scored unit (56 units over the 47 fields: the five dimensions count text and value separately; `scope`, `tether` and `persistence` count their sub-fields). Rule (§4.3): **pass** = repeatability threshold met by ≥ 3 of 4 extractors and cross-model threshold met; **interpretive** (not comparable) = repeatability met by ≥ 3 but cross-model missed; **cut** = repeatability missed by ≥ 2 extractors. Statistics: Fleiss κ (coded, boolean, coded-list first element), judge-equivalence pair rate (free text), ICC(2,1) (numbers). Flags: *borderline* = within 0.05 of a threshold; *sparse* = null in ≥ 90 % of outputs (agreement on null is not evidence of extractability).\n')
    scopes = [s for s in ('pooled', 'synthetic', 'conversational', 'pepys') if s in ft['table']]
    L.append('| Scope | ' + ' | '.join(scopes) + ' |\n|---|' + '---|' * len(scopes))
    for oc in ('pass', 'interpretive', 'cut', 'pending'):
        L.append(f'| {oc} | ' + ' | '.join(str(sum(1 for u, s, v in UNITS if ft['table'][sc][u]['outcome'] == oc)) for sc in scopes) + ' |')
    L.append('\n### 1.1 Pooled (150 texts)\n')
    L.append('| Unit | Shape | ' + ' | '.join(f'rep {short[m]}' for m in EXTRACTORS) + ' | cross | cross, populated only | null | non-canon | outcome | per-arm outcome (syn / conv / pepys) | flags |')
    L.append('|---|---|' + '---|' * len(EXTRACTORS) + '---|---|---|---|---|---|---|')
    for u, s, v in UNITS:
        r = ft['table']['pooled'][u]
        arms = ' / '.join(ft['table'][a][u]['outcome'] if a in ft['table'] else '—' for a in ARMS)
        nn = r['cross'].get('rate_nonnull') if isinstance(r.get('cross'), dict) else None
        flags = ', '.join(x for x, y in (('borderline', r['borderline']), ('sparse', r['sparse']), ('null-driven', s in ('T', 'S', 'L') and r['outcome'] == 'pass' and nn is not None and nn < 0.60), ('value never populated', r['outcome'] == 'pending')) if y)
        L.append(f'| `{u}` | {s} | ' + ' | '.join(fmt(r['stat_repeat'].get(m)) for m in EXTRACTORS) + f" | {fmt(r['stat_cross'])} | {fmt(nn)} | {fmt(r['null_rate'])} | {fmt(r['noncanonical_rate'])} | **{r['outcome']}** | {arms} | {flags} |")
    L.append(chr(10) + '"cross, populated only" (free-text units) is the same judge-equivalence rate computed over populated answers only, so that agreement on null does not carry a sparse field; it is descriptive, the outcome follows the frozen rule. *null-driven* marks a pass whose populated-only cross rate is below the 0.60 threshold. "value never populated" marks numeric slots no extractor filled (ICC undefined).')
    for a in ARMS:
        if a not in ft['table']: continue
        L.append(f'\n### 1.2 {a} arm ({ft["texts_per_arm"].get(a)} texts)\n')
        L.append('| Unit | ' + ' | '.join(f'rep {short[m]}' for m in EXTRACTORS) + ' | cross | null | outcome | flags |')
        L.append('|---|' + '---|' * len(EXTRACTORS) + '---|---|---|---|')
        for u, s, v in UNITS:
            r = ft['table'][a][u]
            flags = ', '.join(x for x, y in (('borderline', r['borderline']), ('sparse', r['sparse'])) if y)
            L.append(f'| `{u}` | ' + ' | '.join(fmt(r['stat_repeat'].get(m)) for m in EXTRACTORS) + f" | {fmt(r['stat_cross'])} | {fmt(r['null_rate'])} | {r['outcome']} | {flags} |")
    # ---- validity
    L.append('\n### 1.3 Output validity per extractor\n\n| Extractor | calls | valid JSON | invalid |\n|---|---|---|---|')
    for m, c in ft['counts'].items(): L.append(f"| {m} | {c.get('calls', 0)} | {c.get('valid', 0)} | {c.get('invalid', 0)} |")
    # ---- task a
    L.append('\n## 2. Task (a): salience-weighted vs recency-weighted retention (k = 3)\n')
    L.append('Pass (§5.2): mean over blocks of (salience hit rate − recency hit rate) ≥ 0.10 for ≥ 3 of 4 extractors. `S_all` is the pre-registered score; the single-component rows show which component carries any effect.\n')
    for arm in [a for a in ARMS if a in ta['per_arm']] + ['pooled']:
        o = ta['per_arm'][arm] if arm != 'pooled' else ta['pooled']
        L.append(f"\n**{arm}** — recency mean {fmt(o['recency_mean'])}, random floor {fmt(o['random_mean'])}\n")
        L.append('| Policy | ' + ' | '.join(f'{short[m]} hit / Δ' for m in EXTRACTORS) + ' | extractors ≥ +0.10 | pass |\n|---|' + '---|' * len(EXTRACTORS) + '---|---|')
        for pol in ('S_all', 'S_intensity', 'S_linkage', 'S_persistence'):
            d = o[pol]
            L.append(f'| {pol} | ' + ' | '.join(f"{fmt(d[m]['mean_salience_hit'])} / {fmt(d[m]['mean_diff_vs_recency'])}" for m in EXTRACTORS) + f" | {d['models_meeting_10pt']} | {'**yes**' if d['pass'] else 'no'} |")
    # ---- task b
    L.append('\n## 3. Task (b): does a stated `self_position` change interpretation?\n')
    if tb:
        p = tb['pooled']
        L.append(f"Items: {tb['items']} synthetic texts with a stated self-position (M1 modal artifact; authored span substituted for {tb['authored_span_used']} where M1 extracted null). Raters: the four extractors × 3 repeats, conditions A (base), B (+ self_position), B′ (+ `context.place`, control). Reference = each rater's modal reading under A.\n")
        L.append(f"**Pooled over `arc` / `trajectory` / `need`:** shift with self_position = **{fmt(p['shift_B_three_coded_fields'])}** (n = {p['readings_B']}); control-field shift = **{fmt(p['shift_control_three_coded_fields'])}** (n = {p['readings_control']}). Threshold (§6.2): ≥ 0.20 and < 0.10 → **{'PASS' if tb['pass'] else 'FAIL'}**.\n")
        L.append('| Field | shift B | shift control |\n|---|---|---|')
        for f, d in p['per_field'].items(): L.append(f"| `{f}` | {fmt(d['shift_B'])} | {fmt(d['shift_control'])} |")
        L.append('\n| Rater | shift B | shift control |\n|---|---|---|')
        for m, d in p['per_rater'].items(): L.append(f"| {m} | {fmt(d['shift_B'])} | {fmt(d['shift_control'])} |")
    else: L.append('_not run_')
    # ---- spend
    L.append('\n## 4. Spend actually incurred (list prices, from per-call usage)\n\n| Model | calls | input | cached input | cache write | output | USD |\n|---|---|---|---|---|---|---|')
    for m, d in spend['by_model'].items(): L.append(f"| {m} | {d['calls']} | {d['input_tokens']:,} | {d['cached_input_tokens']:,} | {d['cache_write_tokens']:,} | {d['output_tokens']:,} | {d['usd']:.2f} |")
    L.append(f"| **total (main run + judge + raters)** | {spend['calls']} | | | | | **{spend['total_usd']:.2f}** |")
    L.append(f"| pilot (excluded from scoring) | {spend_pilot['calls']} | | | | | {spend_pilot['total_usd']:.2f} |")
    L.append(f"\nBudget USD 80. Grand total including pilot and probes: see `spend.json`, `spend_pilot.json` and `raw/pilot/kimi-k2.6_probe_*.json` (two probe calls ≈ USD 0.06).")
    open(os.path.join(EXP, 'RESULTS.md'), 'w', encoding='utf-8', newline='\n').write('\n'.join(L) + '\n')
    print('RESULTS.md written')

if __name__ == '__main__':
    main()
